def _get_err_indices(self, coord_name):
    """
    Get error indices corresponding to a coordinate.

    Args:
        coord_name (str): Name of the coordinate for which to find error indices.

    Returns:
        err_indices (list): List of error indices corresponding to the specified coordinate.
    """
    if coord_name not in self.coords:
        raise ValueError(f"Coordinate name {coord_name} not found in dataset")

    coord_indexes = []
    for dim_name, dim in self.coords[coord_name].items():
        if dim.name not in self.variables:
            raise ValueError(f"Coordinate name {coord_name} not found in dataset")
        coord_indexes.append(self.variables[dim.name].indexes)

    err_indices = []
    for i, indexes in enumerate(coord_indexes):
        if i == 0:
            err_indices.extend(indexes)
        else:
            err_indices = np.intersect1d(err_indices, indexes)

    return err_indices

def is_fill_request_seq(seq):
    """
    Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    from ...elements.fill_request import FillRequest
    from ...elements.source import Source

    if isinstance(seq, FillRequest):
        return True
    elif isinstance(seq, Sequence) and not isinstance(seq, Source):
        return any(isinstance(el, FillRequest) for el in seq)
    else:
        return False

