def status_str(self, prefix=''):
    """Return string representation of validation log, with optional prefix."""
    status_str_list = []
    for field in self.fields:
        if field.is_valid:
            status_str_list.append('{}OK{}'.format(prefix, field.name))
        else:
            status_str_list.append('{}FAIL{}'.format(prefix, field.name))
