def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """

    # Verify that the 'type' in the spec is valid
    _verify_type(self, inventory, None)

    # Verify that the inventory keys match the required keys
    required_keys = set(self.required_keys)
    inventory_keys = set(inventory.keys())
    if not required_keys.issubset(inventory_keys):
        raise InventoryFormatException("Missing required key in inventory: " +
            ', '.join(required_keys.difference(inventory_keys)), None)

    # Verify that the inventory values are of the correct type
    for key, spec in self.spec.items():
        if spec.get('required', False):
            if key not in inventory.keys():
                raise InventoryFormatException("Required key not found in inventory: " + key, None)
            if not _validate_spec(self, inventory[key], spec):
                raise InventoryFormatException("Invalid value for key: " + key, None)

    # Verify that the inventory doesn't have any extra keys not in the spec
    if not self.ignore_extra_keys:
        for key in inventory.keys():
            if key not in self.spec.keys():
                raise InventoryFormatException("Extra key in inventory not allowed: " + key, None)

    # Validate the spec version, if applicable
    if extract_spec_version:
        spec_version = _extract_spec_version(inventory.get('type'))
        if spec_version is None or spec_version not in self.spec_versions:
            raise InventoryFormatException("Unsupported spec version: " + str(spec_version), None)
    elif self.spec_version:
        if self.spec_version not in self.spec_versions:
            raise InventoryFormatException("Unsupported spec version: " + str(self.spec_version), None)

    return inventory

def get_logical_path_map(inventory, version):
    logical_path_map = {}
    for file in inventory['files']:
        if file['version'] == version:
            logical_path = file['logical_path']
            content_files = set()
            for content_file in inventory['files']:
                if content_file['logical_path'] == logical_path:
                    content_files.add(content_file)
            logical_path_map[logical_path] = content_files
    return logical_path_map

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    # Check the structure of the fixity block
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block should be a dictionary")

    for file_name, hashes in fixity.items():
        if not isinstance(hashes, dict):
            raise ValueError("Fixity hashes should be a dictionary")

        for hash_type, hash_value in hashes.items():
            if hash_type not in ("md5", "sha256"):
                raise ValueError("Unknown hash type {}".format(hash_type))

            if not isinstance(hash_value, str):
                raise ValueError("Hash value should be a string")

    # Make sure all files in the manifest are referenced in the fixity block
    for file_name in manifest_files:
        if file_name not in fixity:
            raise ValueError("Fixity block is missing hash information for file {}".format(file_name))

    return fixity

