            merged_value = {}
            for subkey, subvalue in value.value:
                if subkey in merged_value:
                    if not isinstance(merged_value[subkey], MappingNode):
                        merged_value[subkey] = [merged_value[subkey], subvalue]
                    else:
                        merged_value[subkey] = merged_value[subkey].value + [subvalue]
                else:
                    merged_value[subkey] = subvalue
            value = MappingNode(merged_value, value.tag)
        result.append((key, value))
    return result

