def subclasses(cls):
    seen = set()
    queue = [cls]

    while queue:
        c = queue.pop()
        seen.add(c)

        for subcls in c.__subclasses__():
            if subcls not in seen:
                queue.append(subcls)

    seen.remove(cls)
    return seen

