def from_ticks(cls, ticks, tz=None):
    if not (0 <= ticks \< 86400000000000):
        raise ValueError("ticks out of bounds (0 <= ticks < 86400000000000)")
    seconds = ticks / 1000000000
    microseconds = (ticks % 1000000000) * 1000
    datetime = datetime.fromtimestamp(seconds, tz)
    datetime = datetime + timedelta(microseconds=microseconds)
    return cls(datetime)

def protocol_handlers(cls, protocol_version=None):
    """Return a dictionary of available Bolt protocol handlers, keyed by version tuple. If an explicit protocol version is provided, the dictionary will contain either zero or one items, depending on whether that version is supported. If no protocol version is provided, all available versions will be returned.

    :param protocol_version: tuple identifying a specific protocol version (e.g. (3, 5)) or None
    :return: dictionary of version tuple to handler class for all relevant and supported protocol versions
    :raise TypeError: if protocol version is not passed in a tuple"""
    if protocol_version is None:
        return {(3, 5): cls.V35, (3, 1): cls.V31, (1, 0): cls.V10, (0, 9): cls.V09}
    elif isinstance(protocol_version, tuple):
        if not len(protocol_version) == 2:
            raise TypeError("Protocol version must be a 2-tuple (e.g. (3, 5))")
        if protocol_version in [cls.V35, cls.V31, cls.V10, cls.V09]:
            return {protocol_version: cls.V35}
        else:
            return {}
    else:
        raise TypeError("Protocol version must be a tuple (e.g. (3, 5))")

