def verifyObject(iface, candidate, tentative=False):
    if not tentative:
        if not iface.providedBy(candidate):
            raise zope.interface.Invalid("Object does not provide interface")

    for method in iface.public_methods:
        if not hasattr(candidate, method):
            raise zope.interface.Invalid(f"Object does not implement method {method}")

        method_impl = getattr(candidate, method, None)
        if not callable(method_impl):
            raise zope.interface.Invalid(f"Object does not implement method {method} as a callable")

        iface_method = getattr(iface, method, None)
        if iface_method is None:
            raise zope.interface.Invalid(f"Method {method} in interface not found")

        iface_method_sig = inspect.signature(iface_method)
        method_sig = inspect.signature(method_impl)
        if iface_method_sig != method_sig:
            raise zope.interface.Invalid(f"Signature of method does not match interface\nExpected:\n{iface_method_sig}\nFound:\n{method_sig}")

    for attribute in iface.public_attributes:
        if not hasattr(candidate, attribute):
            raise zope.interface.Invalid(f"Object does not have attribute {attribute}")

    return True

