def pop(self, key, default=None):
    """
    D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
    If key is not found, d is returned if given, otherwise KeyError is raised.
    """
    if key not in self:
        if default is not None:
            return default
        raise KeyError(key)
    for map in [self._pb.IntMap, self._pb.FloatMap, self._pb.StringMap,
                self._pb.BoolMap]:
        if key in map.keys():
            return map.pop(key)

def popitem(self):
    """Remove and return the (key, value) pair least frequently used.

    This method raises a ``KeyError`` if the dictionary is empty.
    """
    if self._size == 0:
        raise KeyError('dictionary is empty')

    node = self._promote_lfu_node(self._tail)
    key, value = node.key, node.value
    self._remove(node)
    return (key, value)

def popitem(self):
    """Remove and return the `(key, value)` pair least recently used.

    This method raises a `KeyError` if the list is empty.
    """
    # Find the least recently used key-value pair
    least_recently_used = None
    for key in self:
        if least_recently_used is None or self[key] < self[least_recently_used]:
            least_recently_used = key

    # Remove the least recently used key-value pair
    self.pop(least_recently_used)

    # Return the key-value pair
    return (least_recently_used, self[least_recently_used])

def popitem(self):
    """Remove and return the `(key, value)` pair most recently used.

    This method raises a `KeyError` if the dict is empty.
    """
    try:
        key, value = dict.popitem(self)
        return (key, value)
    except KeyError as e:
        raise BadRequestKeyError(str(e))

