        if not hasattr(cls, '_plugin_manager'):
            # Create the plugin manager instance
            cls._plugin_manager = PluginManager()

            # Initialize the plugin manager
            cls._plugin_manager.register(cls._plugin_classes)

        return cls._plugin_manager

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files.

    :param dict parser_dict: the parsed dictionary representation of the specification
    """
    includes = []
    for key, value in parser_dict.items():
        if key == 'include':
            for inc in value:
                includes.append(inc)
    parser_dict['includes'] = includes

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources. """
    defaults = {}
    for arg in self.args:
        # Check if the argument has a default value in the spec
        if arg.spec is not None:
            defaults[arg.name] = arg.spec.value
        # Check if the argument has a default value in other sources
        if arg.source is not None:
            defaults[arg.name] = arg.source.value
    return defaults

def get_deprecated_args(self):
    """Returning dict with options which deprecate others. """

    # initialize an empty dictionary to store the deprecated args and their replacement
    deprecated_args = {}

    # iterate over the arguments of the current function and their values
    for arg, value in self.signature.parameters.items():
        # check if the argument is deprecated using the "deprecated_since" attribute
        if hasattr(value.annotation, "deprecated_since"):
            # if the argument is deprecated, store it in the dictionary along with its replacement
            deprecated_args[arg] = value.annotation.deprecated_since

    return deprecated_args

