def validate_requires_args(self, args):
    """
    Check if all the required arguments have been provided.
    """
    # Get the required argument names
    required_args = [arg.name for arg in self.args if arg.required]

    # Check if all required arguments have been provided
    for required_arg in required_args:
        if required_arg not in args:
            raise Exception("Required argument '{}' not provided.".format(required_arg))

def validate_length_args(self, args):
    """
    Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    for arg_name, arg_value in args.items():
        arg_length = len(arg_value)
        if arg_length > self.MAX_LENGTH:
            raise ValueError(f"Argument {arg_name} has too many values "
                             f"(must be less than {self.MAX_LENGTH} values)")

def validate_min_max_args(args):
    """
    Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """

    # Check if both minimum and maximum values exist
    if 'min_value' in args and 'max_value' in args:
        # Check if the minimum value is less than or equal to the maximum value
        if args['min_value'] <= args['max_value']:
            return True
        else:
            # If the minimum value is greater than the maximum value, raise a TypeError
            raise TypeError("Minimum value must be less than or equal to maximum value")

    # If only one of the minimum or maximum values exists, raise a ValueError
    elif 'min_value' in args or 'max_value' in args:
        raise ValueError("Both minimum and maximum values must be provided")

    # Otherwise, return True
    else:
        return True

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend `vars_dict` with `extra-vars`

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if extra_vars is None:
        return vars_dict
    if not isinstance(extras_vars, list):
        raise ValueError("Unable to merge: List expected")
    for extra_var in extra_vars:
        if extra_var not in vars_dict:
            vars_dict[str(extra_var)] = extra_var
    return vars_dict

def _convert_non_cli_args(self, parser_name, values_dict):
    """
    Casts arguments to correct types by modifying `values_dict` param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    for opt in self._get_opt_parser(parser_name).options:
        try:
            if opt.dest in values_dict:
                values_dict[opt.dest] = opt.convert(values_dict[opt.dest])
        except ValueError:
            if opt.dest == "type":
                values_dict[opt.dest] = "s"
            elif opt.dest == "wrap":
                values_dict[opt.dest] = "single"
            elif opt.dest == "options":
                values_dict[opt.dest] = ""
            else:
                values_dict[opt.dest] = None

def get_plugin_spec_flatten_dict(plugin_dir):
    """
    Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    plugin_spec = yaml.load(open(os.path.join(plugin_dir, 'plugin.yaml')))
    flatten_dict = {}
    for key, value in plugin_spec.items():
        flatten_dict[key] = value
        if isinstance(value, dict):
            for subkey, subvalue in value.items():
                flatten_dict[f'{key}_{subkey}'] = subvalue
    return flatten_dict

